using System.ComponentModel;
using System.Net;
using System.Text.Json;
using Microsoft.Extensions.AI;

// ---------------------------------------------------------------------------
// Configuration – set OPENAI_API_KEY (and optionally OPENAI_MODEL) env vars.
// ---------------------------------------------------------------------------
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

var model = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";

// Build the chat client with automatic function-invocation middleware.
IChatClient client = new OpenAI.OpenAIClient(apiKey)
    .GetChatClient(model)
    .AsIChatClient()
    .AsBuilder()
    .UseFunctionInvocation()
    .Build();

// Instantiate the tools.
var notebook = new Notebook();
var webSearch = new WebSearchTool();

var tools = new AIFunction[]
{
    AIFunctionFactory.Create(webSearch.SearchAsync),
    AIFunctionFactory.Create(notebook.AddNote),
    AIFunctionFactory.Create(notebook.GetNotes),
};

var chatOptions = new ChatOptions { Tools = [.. tools] };

// Conversation history seeded with a system prompt.
List<ChatMessage> history =
[
    new(ChatRole.System,
        """
        You are a research agent. The user will give you a topic.
        Your job:
          1. Search the web for information about the topic (multiple queries if needed).
          2. Take notes on the key findings using the note-taking tool.
          3. After you have gathered enough information, retrieve your notes and
             produce a well-structured summary for the user.
        Always cite sources when possible.
        """),
];

Console.WriteLine("===  Research Agent  ===");
Console.WriteLine("Enter a research topic (or 'exit' to quit):\n");

while (true)
{
    Console.ForegroundColor = ConsoleColor.Cyan;
    Console.Write("> ");
    Console.ResetColor();

    var input = Console.ReadLine();
    if (string.IsNullOrWhiteSpace(input) || input.Equals("exit", StringComparison.OrdinalIgnoreCase))
        break;

    history.Add(new ChatMessage(ChatRole.User, input));

    Console.ForegroundColor = ConsoleColor.DarkGray;
    Console.WriteLine("Researching… (the agent may make several tool calls)\n");
    Console.ResetColor();

    var response = await client.GetResponseAsync(history, chatOptions);

    // Append assistant response to history for multi-turn conversation.
    history.AddRange(response.Messages);

    Console.ForegroundColor = ConsoleColor.Green;
    Console.WriteLine(response.Text);
    Console.ResetColor();
    Console.WriteLine();
}

Console.WriteLine("Goodbye!");

// =========================================================================
//  Web Search Tool – fetches search results via a simple HTTP scrape.
// =========================================================================
sealed class WebSearchTool : IDisposable
{
    private readonly HttpClient _http = new();

    [Description("Search the web for the given query and return a snippet of the results page.")]
    public async Task<string> SearchAsync(
        [Description("The search query string")] string query,
        [Description("Max number of results to return")] int maxResults = 5)
    {
        try
        {
            var encoded = WebUtility.UrlEncode(query);
            // Use DuckDuckGo lite (HTML) – no API key required.
            var url = $"https://lite.duckduckgo.com/lite?q={encoded}";
            var html = await _http.GetStringAsync(url);

            // Extract a useful text snippet from the HTML.
            var text = StripHtml(html);

            // Trim to a reasonable size so the model context isn't flooded.
            const int limit = 4000;
            if (text.Length > limit)
                text = text[..limit] + "\n… (results truncated)";

            return string.IsNullOrWhiteSpace(text)
                ? "No results found."
                : text;
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}";
        }
    }

    public void Dispose() => _http.Dispose();

    private static string StripHtml(string html)
    {
        // Lightweight tag removal – good enough for search snippets.
        var text = System.Text.RegularExpressions.Regex.Replace(html, "<[^>]+>", " ");
        text = WebUtility.HtmlDecode(text);
        // Collapse whitespace.
        text = System.Text.RegularExpressions.Regex.Replace(text, @"\s+", " ").Trim();
        return text;
    }
}

// =========================================================================
//  Notebook Tool – simple in-memory note storage.
// =========================================================================
sealed class Notebook
{
    private readonly List<string> _notes = [];

    [Description("Save a research note. Use this to record important findings.")]
    public string AddNote([Description("The note text to save")] string note)
    {
        _notes.Add(note);
        return $"Note #{_notes.Count} saved.";
    }

    [Description("Retrieve all saved research notes.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes have been saved yet.";

        return string.Join("\n",
            _notes.Select((n, i) => $"[{i + 1}] {n}"));
    }
}

